// ---------- aprovação: plano de criação no eLabFTW ----------

function separarNome(nome) {
  const partes = texto(nome, 120).split(/\s+/).filter(Boolean);
  if (!partes.length) return { firstname: 'Proponente', lastname: 'PD&I' };
  return { firstname: partes[0], lastname: partes.slice(1).join(' ') || '-' };
}

function acharUsuario(usuarios, email) {
  const e = String(email || '').trim().toLowerCase();
  return usuarios.find((u) => u && String(u.email || '').trim().toLowerCase() === e) || null;
}

function dataIso(s) {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(s || '').trim());
  if (m) return `${m[3]}-${m[2]}-${m[1]}`;
  return /^\d{4}-\d{2}-\d{2}$/.test(String(s || '').trim()) ? String(s).trim() : '';
}

const ACOMPLETAR = (t) => `<p><em>A completar: ${esc(t)}</em></p>`;

function corpoDoPlano(registro, d) {
  const p = (t) => `<p>${esc(t).replace(/\n/g, '<br>')}</p>`;
  const lista = (itens) => `<ul>${itens.map((t) => `<li>${esc(t)}</li>`).join('')}</ul>`;
  const equipe = (d.equipe_lista || []).map((x) => [x.nome, x.papel].filter(Boolean).join(' — '));
  const produtos = String(d.produtos || '').split(/,\s*/).filter(Boolean);
  const cuidados = String(d.cuidados || '').split(/,\s*(?=[A-ZÁÉÍÓÚ])/).filter(Boolean);
  return `<p><em>Plano criado a partir da proposta aprovada. Revise cada seção, complete o que está marcado "A completar" e marque as etapas da lista de verificação (Diretrizes, seção 3).</em></p>
<h2>1. Combinados da equipe</h2>${p(`Pesquisador-líder: ${registro.proponente_nome}.`)}${equipe.length ? lista(equipe) : ''}${ACOMPLETAR('quem faz o quê, frequência das conversas de pesquisa, como as decisões são registradas e previsão de autoria.')}
<h2>2. Problema e pergunta</h2>${d.problema ? p(d.problema) : ACOMPLETAR('a situação real e a pergunta principal.')}
<h2>3. Por que importa</h2>${ACOMPLETAR('para quem o resultado é útil e o que muda se a pergunta for respondida.')}
<h2>4. O que já se sabe</h2>${d.estado_arte ? p(d.estado_arte) : ''}${ACOMPLETAR('três a cinco referências-chave, inclusive uma com resultado contrário.')}
<h2>5. Objetivos</h2>${d.objetivos ? p(d.objetivos) : ACOMPLETAR('objetivo geral e específicos.')}
<h2>6. Método</h2>${d.abordagem ? p(`${d.abordagem}${d.justificativa ? `. ${d.justificativa}` : ''}`) : ''}${ACOMPLETAR('contexto, etapas e como o resultado será avaliado.')}
<h2>7. Plano de evidências</h2>${ACOMPLETAR('o que será registrado, onde fica e para que serve (cada evidência vira um recurso "Evidência").')}
<h2>8. Produtos e marcos</h2>${produtos.length ? lista(produtos) : ''}${d.inicio || d.termino ? p(`Período previsto: ${[d.inicio, d.termino].filter(Boolean).join(' a ')}.`) : ''}${ACOMPLETAR('marcos intermediários e previsão de cada produto.')}
<h2>9. Cuidados</h2>${cuidados.length ? p('Declarados na proposta:') + lista(cuidados) : p('Nenhum item marcado na proposta.')}${ACOMPLETAR('base legal e anonimização de dados pessoais, instrumento de sigilo do parceiro, necessidade de Comitê de Ética e como o uso de IA será declarado (Diretrizes, seção 10).')}
<h2>10. Referências</h2>${ACOMPLETAR('no formato ABNT NBR 6023.')}`;
}

function planoAprovacao({ registro, usuarios, modeloFicha, modeloPlano, decisor, agora, cfg }) {
  const d = JSON.parse(registro.dados_json || '{}');
  const meta = JSON.parse((modeloFicha && modeloFicha.metadata) || '{}');
  const ef = meta.extra_fields || {};
  const pre = (campos, k, v) => { if (campos[k] && v) campos[k].value = v; };
  const temParceiro = /parceiro|fomento/i.test(d.vinculo_projeto || '') || /^sim/i.test(d.parceiros || '');
  const vinculo = d.vinculo_projeto || (temParceiro ? 'Projeto com parceiro' : 'Projeto interno');
  const equipe = d.equipe_lista || [];
  const pesquisadores = [registro.proponente_nome, ...equipe.filter((x) => /pesquisador/i.test(x.papel)).map((x) => x.nome)].filter(Boolean);
  const colaboradores = equipe.filter((x) => !/pesquisador/i.test(x.papel)).map((x) => [x.nome, x.papel].filter(Boolean).join(' — '));
  pre(ef, 'Vínculo', vinculo);
  pre(ef, 'Parceiro', texto(d.parceiro || (temParceiro ? d.parceiros_detalhes : ''), 250));
  pre(ef, 'Pesquisador-líder', registro.proponente_nome);
  pre(ef, 'Pesquisadores', pesquisadores.join('; '));
  pre(ef, 'Colaboradores e orientador', colaboradores.join('; '));
  pre(ef, 'Início', dataIso(d.inicio));
  pre(ef, 'Término previsto', dataIso(d.termino));
  pre(ef, 'Proposta no Comitê de PD&I', cfg.urlPlanilha);
  meta.extra_fields = ef;
  const p = (t) => `<p>${esc(t).replace(/\n/g, '<br>')}</p>`;
  const body = `<p><em>Ficha criada a partir da proposta ${esc(registro.id_projeto)}, aprovada em ${esc(agora.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }))} por ${esc(decisor)}. Mantenha a situação atualizada e ligue a esta ficha o plano, o caderno, as evidências e os produtos.</em></p>
<h2>Resumo</h2>${p(d.descricao || d.problema || '')}${d.objetivos ? `<h3>Objetivos e resultados esperados</h3>${p(d.objetivos)}` : ''}
<h2>Combinados da equipe</h2><p>Estão no plano de pesquisa.</p><h2>Registros fora daqui</h2><p><em>Repositórios, pastas, planilhas e documentos onde está o trabalho do projeto.</em></p>`;

  const metaPlano = JSON.parse((modeloPlano && modeloPlano.metadata) || '{}');
  const efp = metaPlano.extra_fields || {};
  pre(efp, 'Vínculo', vinculo);
  pre(efp, 'Abordagem metodológica', d.abordagem);
  pre(efp, 'Início previsto', dataIso(d.inicio));
  pre(efp, 'Término previsto', dataIso(d.termino));
  pre(efp, 'Proposta no Comitê de PD&I', cfg.urlPlanilha);
  metaPlano.extra_fields = efp;

  const existente = acharUsuario(usuarios, registro.proponente_email);
  const membros = equipe
    .map((x) => acharUsuario(usuarios, x.email))
    .filter((u) => u && (!existente || Number(u.userid) !== Number(existente.userid)))
    .map((u) => Number(u.userid));
  return {
    usuarioId: existente ? Number(existente.userid) : null,
    novoUsuario: existente ? null : { ...separarNome(registro.proponente_nome), email: registro.proponente_email, team: cfg.equipe },
    ficha: { template: cfg.modeloFicha, title: registro.titulo, metadata: JSON.stringify(meta), body },
    plano: { template: cfg.modeloPlano, title: `Plano de pesquisa — ${registro.titulo}`.slice(0, 250), metadata: JSON.stringify(metaPlano), body: corpoDoPlano(registro, d) },
    membrosExistentes: [...new Set(membros)],
    grupoNome: `Projeto – ${registro.titulo}`.slice(0, 250),
  };
}

function permissoesGrupo(grupoId) {
  const can = JSON.stringify({ teams: [], teamgroups: [Number(grupoId)], users: [] });
  return { canread_base: 20, canread: can, canwrite_base: 20, canwrite: can };
}

